head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.rep_isu_cd = null; // 수정 시 key로 사용하는 전역변수
// 상장관련공통함수

scwin.fn_GetPar, scwin.fn_SetPar;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        // 부모창으로부터 param을 받아온다.
        await scwin.getParam();
        MxTab_1.setSelectedTabIndex(1);
        tab_opin_1.setSelectedTabIndex(1);

        // round처리
        $c.libRoundPanel.PanelToGroupBox(panel_Top);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF35701.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name dts_MngInfo_OnLoadCompleted
 * @description dts_MngInfo 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_MngInfo_OnLoadCompleted = function(rowcount) {
    try {
        // dataSet 로딩 후 경영권 방어수단 도입여부 setting 한다.
        const gay_0 = dts_MngInfo.getCellData(1, "C0_GAY");
        const gay_1 = dts_MngInfo.getCellData(1, "C1_GAY");
        const gay_2 = dts_MngInfo.getCellData(1, "C2_GAY");
        const gay_3 = dts_MngInfo.getCellData(1, "C3_GAY");
        const gay_4 = dts_MngInfo.getCellData(1, "C4_GAY");
        const say_0 = dts_MngInfo.getCellData(1, "C0_SAY");
        const say_1 = dts_MngInfo.getCellData(1, "C1_SAY");
        const say_2 = dts_MngInfo.getCellData(1, "C2_SAY");
        const say_3 = dts_MngInfo.getCellData(1, "C3_SAY");
        const say_4 = dts_MngInfo.getCellData(1, "C4_SAY");
        const cvey_0 = dts_MngInfo.getCellData(1, "C0_CVEY");
        const cvey_1 = dts_MngInfo.getCellData(1, "C1_CVEY");
        const cvey_2 = dts_MngInfo.getCellData(1, "C2_CVEY");
        const cvey_3 = dts_MngInfo.getCellData(1, "C3_CVEY");
        const cvey_4 = dts_MngInfo.getCellData(1, "C4_CVEY");

        // 세 조건 중 하나라도 yes 일 경우  경영권 방어수단 도입여부를 yes로 세팅
        if (gay_0 === "1" || say_0 === "1" || cvey_0 === "1") {
            rd_mdy_2_0.setValue("1");
        } else {
            rd_mdy_2_0.setValue("2");
        }
        if (gay_1 === "1" || say_1 === "1" || cvey_1 === "1") {
            rd_mdy_2_1.setValue("1");
        } else {
            rd_mdy_2_1.setValue("2");
        }
        if (gay_2 === "1" || say_2 === "1" || cvey_2 === "1") {
            rd_mdy_2_2.setValue("1");
        } else {
            rd_mdy_2_2.setValue("2");
        }
        if (gay_3 === "1" || say_3 === "1" || cvey_3 === "1") {
            rd_mdy_2_3.setValue("1");
        } else {
            rd_mdy_2_3.setValue("2");
        }
        if (gay_4 === "1" || say_4 === "1" || cvey_4 === "1") {
            rd_mdy_2_4.setValue("1");
        } else {
            rd_mdy_2_4.setValue("2");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35701.dts_MngInfo_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_MngInfo_OnLoadError
 * @description dts_MngInfo 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_MngInfo_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_MngInfo);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF35701.dts_MngInfo_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_ValInfo_OnLoadCompleted
 * @description dts_ValInfo 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_ValInfo_OnLoadCompleted = async function(rowcount) {
    try {
        const isur_cd = dts_ValInfo.getCellData(1, "ISUR_CD");
        const ccnt_1 = (dts_ValInfo.getCellData(1, "C1_CPT_CHG_CNT") === "" ? 0 : parseInt(dts_ValInfo.getCellData(1, "C1_CPT_CHG_CNT")));
        const ccnt_2 = (dts_ValInfo.getCellData(1, "C2_CPT_CHG_CNT") === "" ? 0 : parseInt(dts_ValInfo.getCellData(1, "C2_CPT_CHG_CNT")));
        const ccnt_3 = (dts_ValInfo.getCellData(1, "C3_CPT_CHG_CNT") === "" ? 0 : parseInt(dts_ValInfo.getCellData(1, "C3_CPT_CHG_CNT")));
        const ccnt_4 = (dts_ValInfo.getCellData(1, "C4_CPT_CHG_CNT") === "" ? 0 : parseInt(dts_ValInfo.getCellData(1, "C4_CPT_CHG_CNT")));

        // 자본금 변동회수가 0보다 클경우 변동 원인을 서버에 요청한다.
        if (ccnt_1 > 0) {
            await scwin.listSync41(isur_cd, 1);
        }
        if (ccnt_2 > 0) {
            await scwin.listSync42(isur_cd, 2);
        }
        if (ccnt_3 > 0) {
            await scwin.listSync43(isur_cd, 3);
        }
        if (ccnt_4 > 0) {
            await scwin.listSync44(isur_cd, 4);
        }

        // 각 회차의 데이터 존재여부를 판단하기 위하여 각 회차의 주가 존재여부를 가져온다.
        const isExist_1 = (dts_ValInfo.getCellData(1, "C1_STKPRC") === "" ? false : true);
        const isExist_2 = (dts_ValInfo.getCellData(1, "C2_STKPRC") === "" ? false : true);
        const isExist_3 = (dts_ValInfo.getCellData(1, "C3_STKPRC") === "" ? false : true);
        const isExist_4 = (dts_ValInfo.getCellData(1, "C4_STKPRC") === "" ? false : true);

        // 누적변동 횟수를 세팅한다.
        const ccnt_a_1 = ccnt_1;
        const ccnt_a_2 = ccnt_1 + ccnt_2;
        const ccnt_a_3 = ccnt_1 + ccnt_2 + ccnt_3;
        const ccnt_a_4 = ccnt_1 + ccnt_2 + ccnt_3 + ccnt_4;
        txb_chg_acnt_4_1.setValue((isExist_1 ? (ccnt_a_1 === 0 ? "" : ccnt_a_1) : ""));
        txb_chg_acnt_4_2.setValue((isExist_2 ? (ccnt_a_2 === 0 ? "" : ccnt_a_2) : ""));
        txb_chg_acnt_4_3.setValue((isExist_3 ? (ccnt_a_3 === 0 ? "" : ccnt_a_3) : ""));
        txb_chg_acnt_4_4.setValue((isExist_4 ? (ccnt_a_4 === 0 ? "" : ccnt_a_4) : ""));

        // 누적자본금을 세팅한다.
        const cp_amt_1 = (dts_ValInfo.getCellData(1, "C1_CPT_CHG_AMT") === "" ? 0 : parseInt(dts_ValInfo.getCellData(1, "C1_CPT_CHG_AMT")));
        const cp_amt_2 = (dts_ValInfo.getCellData(1, "C2_CPT_CHG_AMT") === "" ? 0 : parseInt(dts_ValInfo.getCellData(1, "C2_CPT_CHG_AMT")));
        const cp_amt_3 = (dts_ValInfo.getCellData(1, "C3_CPT_CHG_AMT") === "" ? 0 : parseInt(dts_ValInfo.getCellData(1, "C3_CPT_CHG_AMT")));
        const cp_amt_4 = (dts_ValInfo.getCellData(1, "C4_CPT_CHG_AMT") === "" ? 0 : parseInt(dts_ValInfo.getCellData(1, "C4_CPT_CHG_AMT")));
        const cp_amt_a_1 = cp_amt_1;
        const cp_amt_a_2 = cp_amt_1 + cp_amt_2;
        const cp_amt_a_3 = cp_amt_1 + cp_amt_2 + cp_amt_3;
        const cp_amt_a_4 = cp_amt_1 + cp_amt_2 + cp_amt_3 + cp_amt_4;
        txb_cpt_chg_ac_4_1.setValue(isExist_1 ? (cp_amt_a_1 === 0 ? "" : cp_amt_a_1) : "");
        txb_cpt_chg_ac_4_2.setValue(isExist_2 ? (cp_amt_a_2 === 0 ? "" : cp_amt_a_2) : "");
        txb_cpt_chg_ac_4_3.setValue(isExist_3 ? (cp_amt_a_3 === 0 ? "" : cp_amt_a_3) : "");
        txb_cpt_chg_ac_4_4.setValue(isExist_4 ? (cp_amt_a_4 === 0 ? "" : cp_amt_a_4) : "");
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF35701.dts_ValInfo_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_ValInfo_OnLoadError
 * @description dts_ValInfo 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
