/**
 * @method
 * @name dts_ValCCRInfo_1_OnLoadCompleted
 * @description dts_ValCCRInfo_1 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_ValCCRInfo_1_OnLoadCompleted = function(rowcount) {
    try {
        let rsn_list = "";
        for (let i = 1; i <= dts_ValCCRInfo_1.getRowCount(); i++) {
            rsn_list += dts_ValCCRInfo_1.getCellData(i, "CD_VAL_NM") + ",";
        }
        if (rsn_list !== "") {
            // 마지막  ','  제거한다.
            rsn_list = rsn_list.substr(0, (rsn_list.length - 1));
            txb_chg_rsn_4_1.setValue(rsn_list);
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35701.dts_ValCCRInfo_1_OnLoadCompleted" });
    }
};

