/**
 * @method
 * @name MxTab_1_OnSelChanged
 * @description Mx Tab 1 On Sel Changed 처리
 * @param {*} nIndex nIndex
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.MxTab_1_OnSelChanged = async function(nIndex) {
    try {
        const tIndex = MxTab_1.getSelectedTabIndex();
        // alert(tIndex);
        if (tIndex === 1) {

        } else if (tIndex === 2) {
            await scwin.listSync2();
        } else if (tIndex === 3) {
            await scwin.listSync3();
        } else if (tIndex === 4) {
            await scwin.listSync4();
        } else if (tIndex === 5) {
            await scwin.listSync5();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF35701.MxTab_1_OnSelChanged" });
    }
};

